#include <cstdio>
#include <vector>
#include <queue>
#include <utility>
#include <algorithm>

int main() {
    int a, b;
    if (std::scanf("%d %d", &a, &b) != 2) return 0;

    const int limit = a + b;
    std::vector<std::vector<bool>> visited(
        limit + 1, std::vector<bool>(limit + 1, false)
    );
    std::queue<std::pair<int, int>> q;

    visited[a][b] = true;
    q.push({a, b});

    int ans = 0;

    while (!q.empty()) {
        const auto [x, y] = q.front();
        q.pop();

        ans = std::max(ans, limit - x - y);

        if (x > 2 && !visited[x - 2][y + 1]) {
            visited[x - 2][y + 1] = true;
            q.push({x - 2, y + 1});
        }

        if (y > 2 && !visited[x + 1][y - 2]) {
            visited[x + 1][y - 2] = true;
            q.push({x + 1, y - 2});
        }
    }

    std::printf("%d\n", ans + 1);
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b;
    cin >> a >> b;

    int total = a + b;
    int answer = 1;
    int token = 0;

    vector<int> current{a}, next;
    vector<int> seen(total + 1, -1);

    while (true) {
        next.clear();
        ++token;

        for (int x : current) {
            int y = total - x;

            if (x > 2 && seen[x - 2] != token) {
                seen[x - 2] = token;
                next.push_back(x - 2);
            }
            if (y > 2 && seen[x + 1] != token) {
                seen[x + 1] = token;
                next.push_back(x + 1);
            }
        }

        if (next.empty()) break;

        ++answer;
        --total;
        current.swap(next);
    }

    cout << answer << '\n';
    return 0;
}

#include <cstdio>
#include <vector>

int main() {
    int a, b;
    if (scanf("%d %d", &a, &b) != 2) return 0;

    const int initialSum = a + b;
    std::vector<int> current{a}, next;
    std::vector<int> seen(initialSum + 1, -1);

    int depth = 0;

    while (!current.empty()) {
        next.clear();
        const int sum = initialSum - depth;

        for (int x : current) {
            const int y = sum - x;

            if (x > 2) {
                const int nx = x - 2;
                if (seen[nx] != depth) {
                    seen[nx] = depth;
                    next.push_back(nx);
                }
            }

            if (y > 2) {
                const int nx = x + 1;
                if (seen[nx] != depth) {
                    seen[nx] = depth;
                    next.push_back(nx);
                }
            }
        }

        if (next.empty()) break;
        current.swap(next);
        ++depth;
    }

    printf("%d\n", depth + 1);
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <tuple>
#include <algorithm>

using namespace std;

int main() {
    int a, b;
    cin >> a >> b;

    int limit = a + b + 1;
    vector<vector<bool>> visited(limit, vector<bool>(limit, false));
    queue<tuple<int, int, int>> q;

    visited[a][b] = true;
    q.emplace(a, b, 0);

    int answer = 0;

    while (!q.empty()) {
        auto [x, y, distance] = q.front();
        q.pop();

        answer = max(answer, distance);

        int nx = x - 2, ny = y + 1;
        if (nx > 0 && ny > 0 && !visited[nx][ny]) {
            visited[nx][ny] = true;
            q.emplace(nx, ny, distance + 1);
        }

        nx = x + 1;
        ny = y - 2;
        if (nx > 0 && ny > 0 && !visited[nx][ny]) {
            visited[nx][ny] = true;
            q.emplace(nx, ny, distance + 1);
        }
    }

    cout << answer + 1 << '\n';
    return 0;
}

