#include <utility>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int a, b;
    cin >> a >> b;

    const int sum = a + b;
    const size_t side = static_cast<size_t>(sum + 1);
    vector<unsigned char> visited(side * side, 0);
    queue<pair<int, int>> q;

    auto index = [side](int x, int y) {
        return static_cast<size_t>(x) * side + y;
    };

    visited[index(a, b)] = 1;
    q.emplace(a, b);

    int answer = 0;

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        answer = max(answer, sum - x - y);

        if (x > 2) {
            int nx = x - 2;
            int ny = y + 1;
            if (!visited[index(nx, ny)]) {
                visited[index(nx, ny)] = 1;
                q.emplace(nx, ny);
            }
        }

        if (y > 2) {
            int nx = x + 1;
            int ny = y - 2;
            if (!visited[index(nx, ny)]) {
                visited[index(nx, ny)] = 1;
                q.emplace(nx, ny);
            }
        }
    }

    cout << answer + 1 << '\n';
    return 0;
}

